
import { updateBook as updateBookAPI, deleteBook as deleteBookAPI } from "../Api";
import BookForm from "../components/Bookform";
import BookList from "../components/BookList";

function Books({ books, transactions, refreshData }) {

    async function updateBook(id) {
        const book = books.find(
            item => Number(item.id) === Number(id)
        );

        if (!book) {
            alert("Book not found.");
            return;
        }

        const newTitle = prompt("Enter book title:", book.title);
        if (newTitle === null) return;

        const newAuthor = prompt("Enter author:", book.author);
        if (newAuthor === null) return;

        const newGenre = prompt("Enter genre:", book.genre);
        if (newGenre === null) return;

        const newISBN = prompt("Enter ISBN:", book.isbn);
        if (newISBN === null) return;

        if (
            !newTitle.trim() ||
            !newAuthor.trim() ||
            !newGenre.trim() ||
            !newISBN.trim()
        ) {
            alert("All fields are required.");
            return;
        }

        const duplicateISBN = books.some(
            item =>
                Number(item.id) !== Number(id) &&
                item.isbn.toLowerCase() ===
                    newISBN.trim().toLowerCase()
        );

        if (duplicateISBN) {
            alert("Another book already uses this ISBN.");
            return;
        }

        try {
            await updateBookAPI(id, {
                title: newTitle.trim(),
                author: newAuthor.trim(),
                genre: newGenre.trim(),
                isbn: newISBN.trim()
            });

            await refreshData();

            alert("Book updated successfully.");
        } catch (error) {
            console.error("Update book error:", error);
            alert(error.message || "Unable to update the book.");
        }
    }

    async function deleteBook(id) {
        const activeBorrow = transactions.some(
            transaction =>
                Number(transaction.bookId) === Number(id) &&
                transaction.type === "borrow" &&
                transaction.status === "Borrowed"
        );

        if (activeBorrow) {
            alert(
                "This book cannot be deleted because it is currently borrowed."
            );
            return;
        }

        if (!window.confirm("Are you sure you want to delete this book?")) {
            return;
        }

        try {
            await deleteBookAPI(id);
            await refreshData();
            alert("Book deleted successfully.");
        } catch (error) {
            console.error("Delete book error:", error);
            alert(error.message || "Unable to delete the book.");
        }
    }

    return (
        <main className="main-content">
            <div className="page-title">
                <h2>Book Management</h2>
                <p>Add, update and delete books.</p>
            </div>

            <BookForm
                books={books}
                refreshData={refreshData}
            />

            <BookList
                books={books}
                onUpdate={updateBook}
                onDelete={deleteBook}
            />
        </main>
    );
}

export default Books;
